using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Collections.Generic;using System.ComponentModel;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class CoordinationForm:Form {
Project project;Circuit circuit;string file;List<CoordinationRecord> records;ComboBox kind;ListBox list;TextBox details;Label context;public bool Changed{get;private set;}
public CoordinationForm(Project p,Circuit c,string library){project=p;circuit=c;file=library;records=File.Exists(file)?Coordination.Import(file):new List<CoordinationRecord>();Text="Seletividade e backup — par da rede";Size=new Size(1140,740);MinimumSize=new Size(950,650);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;var tools=new FlowLayoutPanel{Dock=DockStyle.Top,Height=80,Padding=new Padding(8)};kind=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=130};kind.Items.Add("Seletividade");kind.Items.Add("Backup / cascata");kind.SelectedIndex=0;tools.Controls.Add(kind);Add(tools,"Importar CSV",Import);Add(tools,"Modelo do par atual",Template);Add(tools,"Vincular evidência",Attach);Add(tools,"Remover vínculo",Remove);context=new Label{Dock=DockStyle.Top,Height=85,Padding=new Padding(10)};list=new ListBox{Dock=DockStyle.Top,Height=160,HorizontalScrollbar=true};details=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White};Controls.Add(details);Controls.Add(list);Controls.Add(context);Controls.Add(tools);kind.SelectedIndexChanged+=delegate{RefreshRows();};list.SelectedIndexChanged+=delegate{RefreshDetail();};Shown+=delegate{details.SelectionStart=0;details.SelectionLength=0;details.ScrollToCaret();list.Focus();};RefreshRows();}
void Add(FlowLayoutPanel panel,string label,Action action){var b=new Button{Text=label,AutoSize=true};b.Click+=delegate{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Coordenação",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};panel.Controls.Add(b);}
CoordinationKind Kind{get{return (CoordinationKind)kind.SelectedIndex;}}
List<CoordinationRecord> visible=new List<CoordinationRecord>();
void RefreshRows(){var up=Coordination.Upstream(project,circuit);context.Text="Par elétrico automático: "+(up==null?"sem proteção a montante identificada":up.Id+" / "+circuit.Id)+". Motor: "+Coordination.EngineId+".\r\nApenas associação documentada para os dispositivos, ajustes e condições exatos. Sem dados, o resultado é indeterminado. A tabela declarada não substitui a conferência da evidência pelo responsável.";visible=records.Where(x=>x.Kind==Kind).ToList();list.Items.Clear();foreach(var row in visible)list.Items.Add(row.UpstreamReference+" / "+row.DownstreamReference+" / "+row.SystemVoltageV+" V / até "+row.LimitKA+" kA / "+row.Issuer+" / "+row.DataVersion);if(visible.Count>0)list.SelectedIndex=0;else RefreshDetail();}
void RefreshDetail(){var study=Engineering.Analyze(project);var selected=list.SelectedIndex<0?null:visible[list.SelectedIndex];var current=Coordination.EvaluateBinding(project,study,circuit,Kind);var text=new StringBuilder("VÍNCULO SALVO\r\n"+current.Status+"\r\n"+current.Detail);if(selected!=null){var evaluation=Coordination.Evaluate(project,study,circuit,selected);text.Append("\r\n\r\nREGISTRO SELECIONADO\r\n"+evaluation.Status+"\r\n"+evaluation.Detail);}details.Text=text.ToString();details.SelectionStart=0;details.SelectionLength=0;}
void Import(){using(var dialog=new OpenFileDialog{Filter="CSV|*.csv"})if(dialog.ShowDialog(this)==DialogResult.OK){var imported=Coordination.Import(dialog.FileName);Coordination.Export(imported,file);records=imported;RefreshRows();}}
void Template(){using(var dialog=new SaveFileDialog{Filter="CSV|*.csv",FileName="par-coordenacao.csv"})if(dialog.ShowDialog(this)==DialogResult.OK){if(String.Equals(Path.GetFullPath(dialog.FileName),Path.GetFullPath(file),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Use outro nome para preservar a biblioteca.");Coordination.Export(new[]{Coordination.Template(project,circuit,Kind)},dialog.FileName);}}
void Attach(){if(list.SelectedIndex<0)return;Coordination.Attach(project,circuit,visible[list.SelectedIndex]);Changed=true;DialogResult=DialogResult.OK;Close();}
void Remove(){if(Kind==CoordinationKind.Selectivity)circuit.SelectivityEvidence=null;else circuit.BackupEvidence=null;Changed=true;DialogResult=DialogResult.OK;Close();}
}
partial class Studio{void ConfigureCoordination(){if(circuit==null)throw new InvalidOperationException("Selecione o circuito a jusante.");using(var form=new CoordinationForm(project,circuit,Path.Combine(userData,"pares-coordenacao.csv")))if(form.ShowDialog(this)==DialogResult.OK&&form.Changed){Change();tabs.SelectedTab=studyPage;}}}
}
